	start : BOOL;
	stop : BOOL;
	auto : BOOL;
	a : BOOL;
	b : BOOL;
	c : BOOL;
	motor : BOOL;
	lamp : BOOL;
	latch : BOOL;
	x : BOOL;
	y : BOOL;
	speed : INT;
	i : INT;
	j : INT;
	t1 : TON;
	q : BOOL;
END_VAR
%LANGUAGE LD
%NETWORK "Start the motor"
VAR w1 : ANY; END_VAR
// runs while auto is on
w1 := start AND NOT stop;
motor := w1;
lamp := MOVE(EN := w1, 100, OUT => speed).ENO;
%NETWORK "Parallel branch"
x := BRANCH(FEED := auto, a, ??? AND b);
%NETWORK "Set and reset"
latch S= a AND b;
latch R= c;
%NETWORK "Timer"
q := t1(IN := a, PT := T#1S).Q;
%NETWORK "Edge and compare"
y := RISING(a) AND GT(EN := c, i, j);
%NETWORK "Two coils"
y := x := a OR NOT b;
%NETWORK "Jump"
JMP.skip := c;
%NETWORK
skip:
y := TRUE;
%NETWORK "Return"
%DISABLED
RETURN := stop;
END_FUNCTION_BLOCK

