VAR w1 : ANY; END_VAR
// runs while auto is on
w1 := start AND NOT stop;
motor := w1;
lamp := MOVE(EN := w1, 100, OUT => speed).ENO;
%NETWORK "Parallel branch"
x := BRANCH(FEED := auto, a, b);
%NETWORK "Set and reset"
latch S= a AND b;
latch R= c;
%NETWORK "Timer"
q := t1(IN := a, PT := T#1S).Q;
EXECUTE(EN := RAIL(), '');
%NETWORK "Edge and compare"
y := RISING(a) AND GT(EN := c, i, j);
%NETWORK "Two coils"
y := x := a OR NOT b;
%NETWORK "Jump"
JMP.skip := c;
%NETWORK
skip:
y := TRUE;
%NETWORK "Return"
%DISABLED
RETURN := stop;
END_FUNCTION_BLOCK

